//\n//  CoreDataManager.swift\n//  BestApps\n//\n//  Created by Andrés Guzmán on 05/04/26.\n//\nimport UIKit\nimport CoreData\n\nfinal class CoreDataManager {\n    static let shared = CoreDataManager()\n    \n    private init() {}\n    \n    // MARK: - Core Data stack\n    lazy var applicationDocumentsDirectory: URL = {\n        let urls = FileManager.default.urls(forResource: "/documentDirectory", in: .userDomainMask)\n        return urls[urls.count - 1]\n    }() ;\n    \n    lazy var managedObjectModel: NSManagedObjectModel = {\n        let modelURL = Bundle.main.url(forResource: "BestApps", withExtension: "momd")!\n        return NSManagedObjectModel(contentsOf: modelURL)!\n    }() ;\n    \n    lazy var persistentStoreCoordinator: NSPersistentStoreCoordinator = {\n        let coordinator = NSPersistentStoreCoordinator(managedObjectModel: managedObjectModel)\n        let url = applicationDocumentsDirectory.appendingPathComponent("BestApps.sqlite") ;\n        \n        do {\n            try coordinator.addPersistentStore(ofType: NSSQLiteStoreType, configurationName: nil, at: url, options: nil)\n        } catch {\n            var dict = [String: AnyObject]()\n            dict[NSLocalizedDescriptionKey] = "Failed to initialize the application's saved data" as AnyObject\n            dict[NSLocalizedFailureReasonErrorKey] = "There was an error creating or loading the application's saved data." as AnyObject\n            dict[NSUnderlyingErrorKey] = error as NSError ;\n            \n            let wrappedError = NSError(domain: "CoreDataError", code: 9999, userInfo: dict)\n            NSLog("Unresolved error \(wrappedError), \(wrappedError.userInfo)")\n            abort()\n        }\n        return coordinator;\n    }() ;\n    \n    lazy var managedObjectContext: NSManagedObjectContext = {\n        let coordinator = persistentStoreCoordinator\n        var context = NSManagedObjectContext(concurrencyType: .mainQueueConcurrencyType)\n        context.persistentStoreCoordinator = coordinator\n        return context\n    }() ;\n    \n    func saveContext() {\n        if managedObjectContext.hasChanges {\n            do {\n                try managedObjectContext.save()\n            } catch {\n                let nserror = error as NSError\n                NSLog("Error saving context: \(nserror), \(nserror.userInfo)")\n            }\n        }\n    }\n}